1	package zkcircuit
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"path/filepath"
11		"sort"
12		"strconv"
13		"strings"
14		"sync"
15	)
16	
17	// on-disk layout inside the data directory:
18	//
19	//	data.json    – the committed state (JSON envelope, atomically replaced)
20	//	data.json.tmp– staging file for the next commit (rename(2) target)
21	//	lock         – flock file serializing concurrent processes
22	//
23	// The envelope carries an explicit format version: files written by an
24	// incompatible future build are refused rather than silently migrated or
25	// overwritten.
26	const (
27		dirDataFile = "data.json"
28		dirTmpFile  = "data.json.tmp"
29		dirLockFile = "lock"
30	
31		// FormatVersion is the on-disk format this build writes and accepts.
32		FormatVersion = 1
33	)
34	
35	// envelope is the persisted state container.
36	//
37	// Circuits are kept as raw JSON during decoding so persistCircuit's strict
38	// UnmarshalJSON — rather than encoding/json's silent zero-value filling —
39	// decides what a committed circuit record may look like. UnmarshalJSON first
40	// walks the token stream (scanEnvelopeDuplicates) and rejects a repeated
41	// object key anywhere encoding/json would otherwise keep the last value.
42	type envelope struct {
43		Format    int               `json:"format"`
44		Circuits  []persistCircuit  `json:"circuits"`
45		Setups    []persistSetup    `json:"setups"`
46		Jobs      []persistJob      `json:"jobs"`
47		Artifacts []persistArtifact `json:"artifacts,omitempty"`
48	}
49	
50	// envelopeWire is the decoding-only shape: circuit records arrive raw so
51	// their own strict decoder can require every field explicitly.
52	type envelopeWire struct {
53		Format    int               `json:"format"`
54		Circuits  []json.RawMessage `json:"circuits"`
55		Setups    []persistSetup    `json:"setups"`
56		Jobs      []persistJob      `json:"jobs"`
57		Artifacts []persistArtifact `json:"artifacts,omitempty"`
58	}
59	
60	func (e *envelope) UnmarshalJSON(raw []byte) error {
61		// Reject repeated keys before decoding: encoding/json silently keeps the
62		// last value of a duplicate. The walk is layered so a repeated field is
63		// attributed to the record it belongs to (a duplicate "frozen" inside
64		// circuit #3, not a generic envelope complaint).
65		if err := scanEnvelopeDuplicates(raw); err != nil {
66			return err
67		}
68		var wire envelopeWire
69		if err := json.Unmarshal(raw, &wire); err != nil {
70			var se StoreError
71			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
72				return err // an inner record decoder already named the problem
73			}
74			return corruptf("data file envelope is not valid JSON: %v", err)
75		}
76		e.Format = wire.Format
77		e.Setups = wire.Setups
78		e.Jobs = wire.Jobs
79		e.Artifacts = wire.Artifacts
80		if wire.Circuits == nil {
81			e.Circuits = nil
82		} else {
83			e.Circuits = make([]persistCircuit, len(wire.Circuits))
84		}
85		for i, craw := range wire.Circuits {
86			var record persistCircuit
87			if err := json.Unmarshal(craw, &record); err != nil {
88				var se StoreError
89				if errors.As(err, &se) {
90					// Re-tag as one corruption error carrying the record index,
91					// so the detail survives errors.As unwrapping in loadLocked.
92					return StoreError{Kind: ErrDataCorrupt.Kind,
93						Detail: fmt.Sprintf("circuit record #%d: %s", i+1, se.Detail)}
94				}
95				return corruptf("circuit record #%d: %v", i+1, err)
96			}
97			e.Circuits[i] = record
98		}
99		return nil
100	}
101	
102	// scanEnvelopeDuplicates tokenizes the committed envelope and rejects every
103	// repeated object key. Circuit records are scanned one level deep only —
104	// their top-level fields are checked here (with the record's 1-based index
105	// reported), while values such as the constraint definition are skipped and
106	// left to their own strict decoders. Every other envelope member is scanned
107	// recursively so a duplicated key anywhere in committed data fails the read
108	// instead of silently resolving to its last value.
109	func scanEnvelopeDuplicates(raw []byte) error {
110		dec := json.NewDecoder(bytes.NewReader(bytes.TrimSpace(raw)))
111		dec.UseNumber()
112		open, err := dec.Token()
113		if err != nil || open != json.Delim('{') {
114			return corruptf("data file envelope must be a JSON object")
115		}
116		seenTop := make(map[string]bool)
117		for dec.More() {
118			keyTok, err := dec.Token()
119			if err != nil {
120				return corruptf("data file envelope is not valid JSON: %v", err)
121			}
122			key, ok := keyTok.(string)
123			if !ok {
124				return corruptf("data file envelope is not valid JSON")
125			}
126			if seenTop[key] {
127				return corruptf("data file envelope contains duplicate field %q", key)
128			}
129			seenTop[key] = true
130			if key == "circuits" {
131				if err := scanCircuitArrayDuplicates(dec); err != nil {
132					return err
133				}
134				continue
135			}
136			if err := skipValueWithDupKeys(dec, "data file envelope field "+strconv.Quote(key)); err != nil {
137				return err
138			}
139		}
140		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
141			return corruptf("data file envelope is not valid JSON")
142		}
143		if _, err := dec.Token(); err != io.EOF {
144			return corruptf("data file envelope is not valid JSON: trailing data after the object")
145		}
146		return nil
147	}
148	
149	// scanCircuitArrayDuplicates consumes one "circuits" value positioned at its
150	// opening bracket and checks only each record's own top-level keys. A null
151	// array stays the pre-existing "no records" reading.
152	func scanCircuitArrayDuplicates(dec *json.Decoder) error {
153		tok, err := dec.Token()
154		if err != nil {
155			return corruptf("data file envelope field \"circuits\" is not valid JSON: %v", err)
156		}
157		if tok == nil { // null: json.Unmarshal would produce no records
158			return nil
159		}
160		if tok != json.Delim('[') {
161			return corruptf("data file envelope field \"circuits\" must be an array")
162		}
163		index := 0
164		for dec.More() {
165			index++
166			what := fmt.Sprintf("circuit record #%d", index)
167			open, err := dec.Token()
168			if err != nil {
169				return corruptf("%s is not valid JSON: %v", what, err)
170			}
171			if open == nil {
172				return corruptf("%s must be a JSON object, not null", what)
173			}
174			if open != json.Delim('{') {
175				return corruptf("%s must be a JSON object", what)
176			}
177			seen := make(map[string]bool)
178			for dec.More() {
179				keyTok, err := dec.Token()
180				if err != nil {
181					return corruptf("%s is not valid JSON: %v", what, err)
182				}
183				key, ok := keyTok.(string)
184				if !ok {
185					return corruptf("%s is not valid JSON", what)
186				}
187				if seen[key] {
188					return corruptf("%s contains duplicate field %q", what, key)
189				}
190				seen[key] = true
191				// Skip the whole value without descending: nested objects
192				// (definition) own their own strict duplicate checks.
193				var skip json.RawMessage
194				if err := dec.Decode(&skip); err != nil {
195					return corruptf("%s is not valid JSON: %v", what, err)
196				}
197			}
198			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
199				return corruptf("%s is not valid JSON", what)
200			}
201		}
202		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim(']') {
203			return corruptf("data file envelope field \"circuits\" is not valid JSON")
204		}
205		return nil
206	}
207	
208	// skipValueWithDupKeys consumes one JSON value positioned at its first token,
209	// recursively rejecting duplicate object keys.
210	func skipValueWithDupKeys(dec *json.Decoder, what string) error {
211		tok, err := dec.Token()
212		if err != nil {
213			return corruptf("%s is not valid JSON: %v", what, err)
214		}
215		delim, ok := tok.(json.Delim)
216		if !ok {
217			return nil // scalar (including null)
218		}
219		switch delim {
220		case '{':
221			seen := make(map[string]bool)
222			for dec.More() {
223				keyTok, err := dec.Token()
224				if err != nil {
225					return corruptf("%s is not valid JSON: %v", what, err)
226				}
227				key, ok := keyTok.(string)
228				if !ok {
229					return corruptf("%s is not valid JSON", what)
230				}
231				if seen[key] {
232					return corruptf("%s contains duplicate field %q", what, key)
233				}
234				seen[key] = true
235				if err := skipValueWithDupKeys(dec, what+" "+strconv.Quote(key)); err != nil {
236					return err
237				}
238			}
239			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
240				return corruptf("%s is not valid JSON", what)
241			}
242		case '[':
243			index := 0
244			for dec.More() {
245				index++
246				if err := skipValueWithDupKeys(dec, fmt.Sprintf("%s element #%d", what, index)); err != nil {
247					return err
248				}
249			}
250			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim(']') {
251				return corruptf("%s is not valid JSON", what)
252			}
253		}
254		return nil
255	}
256	
257	type persistTerm struct {
258		Wire  int    `json:"wire"`
259		Coeff string `json:"coeff"`
260	}
261	
262	type persistConstraint struct {
263		A []persistTerm `json:"a"`
264		B []persistTerm `json:"b"`
265		C []persistTerm `json:"c"`
266	}
267	
268	// persistDefinition is the canonical, already-validated constraint set bound
269	// to one circuit version. The public/private partition is owned by the
270	// circuit record and is deliberately not duplicated here, so it can never
271	// drift from the declared counts.
272	type persistDefinition struct {
273		Modulus     string              `json:"modulus"`
274		Constraints []persistConstraint `json:"constraints"`
275	}
276	
277	// persistArtifact is a compiled artifact: the version's identity and
278	// constraint count bound to its recomputable SHA-256 hash.
279	type persistArtifact struct {
280		Name        string `json:"name"`
281		Version     int    `json:"version"`
282		Modulus     int64  `json:"modulus"`
283		Constraints int    `json:"constraints"`
284		Hash        string `json:"hash"`
285	}
286	
287	type persistCircuit struct {
288		Name          string             `json:"name"`
289		Version       int                `json:"version"`
290		Constraints   int                `json:"constraints"`
291		PublicInputs  int                `json:"public_inputs"`
292		PrivateInputs int                `json:"private_inputs"`
293		Frozen        bool               `json:"frozen"`
294		Description   string             `json:"description"`
295		Definition    *persistDefinition `json:"definition,omitempty"`
296	}
297	
298	// Strict decoding of committed circuit records.
299	//
300	// A circuit record in data.json must name each of name, version, constraints,
301	// public_inputs, private_inputs, frozen and description exactly once, with
302	// the exact JSON type the writer emits (string / integer / integer / integer
303	// / integer / boolean / string). A missing key, a null, a wrong type or a
304	// repeated key is data corruption and refuses the whole directory read: a
305	// missing or null frozen flag must not silently read as false (turning a
306	// frozen version back into an editable draft), and a repeated key must not
307	// resolve to its last value. An explicit 0, false or "" is an ordinary value
308	// and stays legal. The definition member remains the one optional field: it
309	// may be absent or null (the legacy counts-only state); when present it goes
310	// through the strict persistDefinition decoder.
311	//
312	// Only shape is judged here. The domain rules (non-blank name, positive
313	// version and constraint count, non-negative input counts) keep being
314	// re-checked by validateEnvelope.
315	
316	var persistCircuitFields = []string{
317		"name", "version", "constraints", "public_inputs", "private_inputs",
318		"frozen", "description", "definition",
319	}
320	
321	// storedRecordShape is the shared strict-JSON rule set (definition_schema.go)
322	// tagged for committed data: every structural failure in a stored circuit
323	// record is data corruption, never a bad request.
324	var storedRecordShape = jsonShape{fail: corruptf}
325	
326	func (c *persistCircuit) UnmarshalJSON(raw []byte) error {
327		const what = "stored circuit record"
328		if string(bytes.TrimSpace(raw)) == "null" {
329			return corruptf("%s must be a JSON object, not null", what)
330		}
331		members, err := strictCircuitObject(raw, what)
332		if err != nil {
333			return err
334		}
335	
336		var out persistCircuit
337	
338		requireString := func(key string, dst *string) error {
339			r, err := storedRecordShape.require(members, key, what)
340			if err != nil {
341				return err
342			}
343			v, err := storedRecordShape.string(r, what+" field "+strconv.Quote(key))
344			if err != nil {
345				return err
346			}
347			*dst = v
348			return nil
349		}
350		requireInt := func(key string, dst *int) error {
351			r, err := storedRecordShape.require(members, key, what)
352			if err != nil {
353				return err
354			}
355			v, err := storedRecordShape.int(r, what+" field "+strconv.Quote(key))
356			if err != nil {
357				return err
358			}
359			*dst = v
360			return nil
361		}
362	
363		if err := requireString("name", &out.Name); err != nil {
364			return err
365		}
366		if err := requireInt("version", &out.Version); err != nil {
367			return err
368		}
369		if err := requireInt("constraints", &out.Constraints); err != nil {
370			return err
371		}
372		if err := requireInt("public_inputs", &out.PublicInputs); err != nil {
373			return err
374		}
375		if err := requireInt("private_inputs", &out.PrivateInputs); err != nil {
376			return err
377		}
378		frozenRaw, err := storedRecordShape.require(members, "frozen", what)
379		if err != nil {
380			return err
381		}
382		out.Frozen, err = storedRecordShape.bool(frozenRaw, what+" field "+strconv.Quote("frozen"))
383		if err != nil {
384			return err
385		}
386		if err := requireString("description", &out.Description); err != nil {
387			return err
388		}
389	
390		// definition is the only optional member: absent or null both mean the
391		// counts-only legacy state.
392		if defRaw, present := members["definition"]; present {
393			if string(bytes.TrimSpace(defRaw)) != "null" {
394				var def persistDefinition
395				if err := json.Unmarshal(defRaw, &def); err != nil {
396					var se StoreError
397					if errors.As(err, &se) {
398						return err // already reported as data corruption
399					}
400					return corruptf("%s field %s is not a valid constraint definition: %v", what, strconv.Quote("definition"), err)
401				}
402				out.Definition = &def
403			}
404		}
405	
406		*c = out
407		return nil
408	}
409	
410	// strictCircuitObject decodes one committed circuit record's own member map,
411	// demanding a JSON object with exactly the known top-level fields once.
412	func strictCircuitObject(raw []byte, what string) (map[string]json.RawMessage, error) {
413		return strictObjectMembers(raw, what, persistCircuitFields)
414	}
415	
416	// strictObjectMembers decodes one committed record's own member map,
417	// demanding a JSON object without repeated keys. A non-nil allowed list
418	// restricts which keys may appear; nil allows any key. It scans only the
419	// record's own level: the envelope scanner already attributes a duplicated
420	// top-level key to this record, and nested values such as the constraint
421	// definition own their (more precise) strict decoders. Keys are compared
422	// after JSON unescaping, so a field repeated through a \uXXXX spelling is
423	// still a duplicate, even when both values are identical.
424	func strictObjectMembers(raw []byte, what string, allowedFields []string) (map[string]json.RawMessage, error) {
425		trimmed := bytes.TrimSpace(raw)
426		if len(trimmed) == 0 || trimmed[0] != '{' {
427			return nil, corruptf("%s must be a JSON object", what)
428		}
429		dec := json.NewDecoder(bytes.NewReader(trimmed))
430		dec.UseNumber()
431		open, err := dec.Token()
432		if err != nil || open != json.Delim('{') {
433			return nil, corruptf("%s must be a JSON object", what)
434		}
435		var allowed map[string]bool
436		if allowedFields != nil {
437			allowed = make(map[string]bool, len(allowedFields))
438			for _, f := range allowedFields {
439				allowed[f] = true
440			}
441		}
442		members := make(map[string]json.RawMessage)
443		for dec.More() {
444			keyTok, err := dec.Token()
445			if err != nil {
446				return nil, corruptf("%s is not valid JSON: %v", what, err)
447			}
448			key, ok := keyTok.(string)
449			if !ok {
450				return nil, corruptf("%s is not valid JSON", what)
451			}
452			if allowed != nil && !allowed[key] {
453				return nil, corruptf("%s has unknown field %q", what, key)
454			}
455			if _, repeated := members[key]; repeated {
456				return nil, corruptf("%s contains duplicate field %q", what, key)
457			}
458			var value json.RawMessage
459			if err := dec.Decode(&value); err != nil {
460				return nil, corruptf("%s is not valid JSON: %v", what, err)
461			}
462			members[key] = value
463		}
464		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
465			return nil, corruptf("%s is not valid JSON", what)
466		}
467		if _, err := dec.Token(); err != io.EOF {
468			return nil, corruptf("%s is not valid JSON: trailing data after the object", what)
469		}
470		return members, nil
471	}
