1	package zkcircuit
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"testing"
8	)
9	
10	func dataFilePath(dir string) string { return filepath.Join(dir, dirDataFile) }
11	
12	func readDataFile(t *testing.T, dir string) ([]byte, error) {
13		t.Helper()
14		return os.ReadFile(dataFilePath(dir))
15	}
16	
17	func writeDataFile(t *testing.T, dir string, content []byte) {
18		t.Helper()
19		if err := os.WriteFile(dataFilePath(dir), content, 0o644); err != nil {
20			t.Fatal(err)
21		}
22	}
23	
24	// TestCorruptDataRefused: corrupt, truncated or unsupported-format files
25	// must be reported as read failures, left byte-for-byte untouched, and never
26	// treated as an empty directory or overwritten by a subsequent open.
27	func TestCorruptDataRefused(t *testing.T) {
28		// Seed a valid store first so "empty file" is a truncation case, not a
29		// never-initialized directory.
30		seed := t.TempDir()
31		s, err := Open(seed)
32		if err != nil {
33			t.Fatal(err)
34		}
35		readyCircuit(t, s, "c", 1)
36		if err := s.Close(); err != nil {
37			t.Fatal(err)
38		}
39		valid, err := readDataFile(t, seed)
40		if err != nil {
41			t.Fatal(err)
42		}
43	
44		cases := []struct {
45			name    string
46			content []byte
47		}{
48			{"garbage", []byte("this is not json at all")},
49			{"empty", []byte{}},
