11	// capture runs fn with os.Stdout/os.Stderr redirected, returning what was
12	// written. The data commands never share these fds with other goroutines in
13	// these tests.
14	func capture(t *testing.T, fn func()) (stdout, stderr string) {
15		t.Helper()
16		origOut, origErr := os.Stdout, os.Stderr
17		rOut, wOut, err := os.Pipe()
18		if err != nil {
19			t.Fatal(err)
20		}
21		rErr, wErr, err := os.Pipe()
22		if err != nil {
23			t.Fatal(err)
24		}
25		os.Stdout, os.Stderr = wOut, wErr
26	
27		var outBuf, errBuf bytes.Buffer
28		doneOut := make(chan struct{})
29		doneErr := make(chan struct{})
30		go func() { defer close(doneOut); outBuf.ReadFrom(rOut) }()
31		go func() { defer close(doneErr); errBuf.ReadFrom(rErr) }()
32	
33		fn()
34	
35		wOut.Close()
36		wErr.Close()
37		os.Stdout, os.Stderr = origOut, origErr
38		<-doneOut
39		<-doneErr
40		rOut.Close()
41		rErr.Close()
42		return outBuf.String(), errBuf.String()
43	}
44	
45	func runCapture(t *testing.T, args ...string) (int, string, string) {
46		t.Helper()
47		code := -999
48		out, errOut := capture(t, func() { code = run(args) })
49		return code, out, errOut
50	}
