// dupEnvelope builds bytes in which field appears twice: one occurrence at
// the field's canonical position (format first, artifacts last), the other
// appended at the end. flip puts the alternate spelling/value at the
// canonical position instead.
func dupEnvelope(t *testing.T, vals map[string]json.RawMessage, field, firstToken, secondToken string,
	firstVal, secondVal json.RawMessage, flip bool) []byte {
	t.Helper()
	atPos, appended := firstToken, secondToken
	atPosVal, appendedVal := firstVal, secondVal
	if flip {
		atPos, appended = secondToken, firstToken
		atPosVal, appendedVal = secondVal, firstVal
	}
	var kvs []envKv
	for _, f := range envelopeTopFields {
		val := vals[f]
		token := strconv.Quote(f)
		if f == field {
			token, val = atPos, atPosVal
		}
		kvs = append(kvs, envKv{keyToken: token, val: val})
	}
	kvs = append(kvs, envKv{keyToken: appended, val: appendedVal})
	var buf bytes.Buffer
	emit := func(kv envKv) {
		buf.WriteString(kv.keyToken)
		buf.WriteByte(':')
		var compact bytes.Buffer
		if err := json.Compact(&compact, kv.val); err != nil {
			t.Fatalf("duplicate value is not valid JSON: %v", err)
		}
		buf.Write(compact.Bytes())
	}
	buf.WriteByte('{')
	for i, kv := range kvs {
		if i > 0 {
			buf.WriteByte(',')
		}
		emit(kv)
	}
	buf.WriteString("}\n")
	return buf.Bytes()
}

